mapper.sql:
		  FROM BTCH_EXE_TXN	A
			  LEFT OUTER JOIN BTCH_BAS B
			  ON A.BTCH_JOB_ID = B.BTCH_JOB_ID
          WHERE 1=1

			AND A.BTCH_EXE_STUS_CD = ${btchExeStusCd}


			AND (A.BTCH_JOB_NM LIKE ('%' || #{btchJobNm} || '%') OR A.BTCH_JOB_ID LIKE ('%' || #{btchJobNm} || '%'))


			AND A.BTCH_START_DTM BETWEEN #{btchStartDtm} AND #{btchFinDtm}


			AND A.BTCH_FIN_DTM BETWEEN #{btchStartDtm} AND #{btchFinDtm}

mapper.select:
/*BtchExeTxnDAO.selectListBtchExeTxn 배치실행내역 목록 조회 */
SELECT A.BTCH_EXE_SEQNO /* 배치실행일련번호 */ , A.BTCH_JOB_ID /* 배치작업ID */ , A.BTCH_PRMT_VAL /* 배치파라미터값 */ , A.USER_ID /* 사용자아이디 */ , A.TAGET_TRT_CSCNT /* 대상처리건수 */ , A.BTCH_EXE_STUS_CD /* 배치실행상태코드 */ , A.BTCH_START_DTM /* 배치시작일시 */ , A.BTCH_FIN_DTM /* 배치완료일시 */ , A.SUCSS_YN /* 성공여부 */ , A.BTCH_ERR_CTNT /* 배치오류내용 */ , B.BTCH_JOB_NM /* 배치작업명 */ , (SELECT CD_NM FROM CMN_CD WHERE CD_GROUP_VAL = 'BTCH_EXE_STUS_CD' AND CD_VAL = A.BTCH_EXE_STUS_CD AND USE_YN = 'Y') BTCH_EXE_STUS_NM
ORDER BY A.BTCH_EXE_SEQNO DESC
